  var VIEWBOXES=[[230.3, 97.4, 296.7, 378.9], [266.4, 97.4, 201.7, 327.6], [173.0, 43.7, 299.9, 381.3], [263.4, 97.4, 201.9, 327.6], [266.4, 97.4, 183.3, 327.6]];
