    var from={};
    for(var l in curPos) from[l]=[curPos[l][0],curPos[l][1]];
    var vbFrom=curVB.slice();
    var t0=null;
    function tick(ts){
      if(t0===null) t0=ts;
      var u=Math.min(1,(ts-t0)/dur);
