    var y=e.clientY-r.top-10;
    if(x+tooltip.offsetWidth>r.width-8) x=e.clientX-r.left-tooltip.offsetWidth-8;
    if(y<4) y=4;
    tooltip.style.left=x+'px';
    tooltip.style.top=y+'px';
  }
  function hideTooltip(){
    tooltip.classList.remove('visible');
